def product_nonzero_values(items: List[int]) -> int:
    result = 1
    found = False
    for x in items:
        if x != 0:
            result *= x
            found = True
    return result if found else 0

def alternating_sum(items: List[int]) -> int:
    total = 0
    for i, x in enumerate(items):
        total += x if i % 2 == 0 else -x
    return total

def count_increases(items: List[int]) -> int:
    total = 0
    for i in range(1, len(items)):
        if items[i] > items[i - 1]:
            total += 1
    return total

def count_decreases(items: List[int]) -> int:
    total = 0
    for i in range(1, len(items)):
        if items[i] < items[i - 1]:
            total += 1
    return total

def sum_values_above_average_floor(items: List[int]) -> int:
    if not items:
        return 0
    avg = sum(items) // len(items)
    return sum(x for x in items if x > avg)

def count_values_above_average_floor(items: List[int]) -> int:
    if not items:
        return 0
    avg = sum(items) // len(items)
