def sum_values_below_average_floor(items: List[int]) -> int:
    if not items:
        return 0
    avg = sum(items) // len(items)
    return sum(x for x in items if x < avg)

def reverse_weighted_sum(items: List[int]) -> int:
    n = len(items)
    return sum((n - i) * x for i, x in enumerate(items))

def sum_prefix_maxima(items: List[int]) -> int:
    total = 0
    current = 0
    seen = False
    for x in items:
        if not seen or x > current:
            current = x
            seen = True
        total += current
    return total

